	@Test
	void allDirectionsPreserveBagWeightsAndHaving(@TempDir Path directory) {
		try (Fixture fixture = new Fixture(directory)) {
			for (boolean leftReverse : new boolean[] { false, true }) {
				for (boolean rightReverse : new boolean[] { false, true }) {
					String patterns = (leftReverse ? "?j ex:pr ?a . " : "?a ex:p ?j . ")
							+ (rightReverse ? "?b ex:qr ?j . " : "?j ex:q ?b . ");
					String query = PREFIX + "SELECT ?b ?a (COUNT(*) AS ?count) (COUNT(?j) AS ?bound) "
							+ "WHERE { " + patterns + " } GROUP BY ?b ?a";
					assertEquals(fixture.generic(query), fixture.sparse(query), query);
					for (long threshold : new long[] { 0L, 1L, 2L, 3L, 7L, 8L, Long.MAX_VALUE }) {
						String having = query + " HAVING (COUNT(*) >= " + threshold + ")";
						assertEquals(fixture.generic(having), fixture.sparse(having), having);
					}
				}
			}
			String count = PREFIX + "SELECT ?a ?b (COUNT(*) AS ?count) WHERE { ?a ex:p ?j . ?j ex:q ?b } "
					+ "GROUP BY ?a ?b";
			List<String> actual = fixture.sparse(count);
			assertEquals(3, actual.size());
			assertTrue(actual.stream().anyMatch(value -> value.contains("count=\"7\"")), actual.toString());
			for (String condition : List.of("2 < COUNT(*)", "COUNT(*) = 2", "COUNT(*) > 9223372036854775807",
					"COUNT(*) >= 2.5", "COUNT(*) >= 2 || COUNT(*) = 1",
					"COUNT(*) >= 2 && (1 / (COUNT(*) - COUNT(*)) > 0)")) {
				String having = count + " HAVING (" + condition + ")";
				assertEquals(fixture.generic(having), fixture.sparse(having), having);
			}
			// Constant folding can erase the Group itself; there is then no aggregate route to force.
			String foldedError = count + " HAVING (COUNT(*) >= 2 && (1 / 0 > 0))";
			assertEquals(fixture.generic(foldedError), fixture.automatic(foldedError));
			assertTrue(fixture.automatic(foldedError).isEmpty());
		}
	}

